	w = rawGet(t, h, "/v1/documents/doc1/snapshots?to=1")
	if got := w.Body.String(); got != "{\"snapshots\":[{\"cursor\":1,\"state\":null}],\"count\":1}\n" {
		t.Fatalf("to=1 body = %q", got)
	}
}

